
import React, { useContext } from 'react';
import { AppContext } from '../App';

interface LogoProps {
  className?: string;
}

// الشعار المستخرج من الصورة المرفقة (Base64)
const DEFAULT_LOGO_BASE64 = 'data:image/png;base64,';

const Logo: React.FC<LogoProps> = ({ className }) => {
  const context = useContext(AppContext);
  const customLogo = context?.customLogo;

  const logoSrc = customLogo || "/logo.png";

  return (
    <div 
      className={`${className} flex items-center justify-center bg-white rounded-full overflow-hidden dark:bg-slate-800 border-[3px] border-[#D4AF37] shadow-[0_4px_15px_rgba(212,175,55,0.3)] transition-transform duration-300 hover:scale-105`}
      aria-label="شعار إعداد حافظ"
      role="img"
    >
      <img 
        src={logoSrc} 
        alt="شعار إعداد حافظ" 
        className="h-full w-full object-cover scale-105" 
      />
    </div>
  );
};

export default Logo;
